type AuthOtherAccountsRow struct {
	ProviderID string  `json:"provider_id"`
	Password   *string `json:"password"`
}

func (q *Queries) AuthOtherAccounts(ctx context.Context, arg AuthOtherAccountsParams) ([]AuthOtherAccountsRow, error) {
	rows, err := q.db.Query(ctx, authOtherAccounts, arg.UserID, arg.ID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuthOtherAccountsRow{}
	for rows.Next() {
		var i AuthOtherAccountsRow
		if err := rows.Scan(&i.ProviderID, &i.Password); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

